def range_add_min(n, ops):
    """Segment tree with lazy propagation: [0, l, r, v] adds v on [l, r]; [1, l, r] asks for min on [l, r]."""
    size = 1
    while size < n: size *= 2
    mn = [0] * (2 * size); lz = [0] * (2 * size)
    for i in range(size, 2 * size):
        if i - size >= n: mn[i] = float("inf")
    for i in range(size - 1, 0, -1): mn[i] = min(mn[2 * i], mn[2 * i + 1])
    def upd(node, nl, nr, l, r, v):
        if r < nl or nr < l: return
        if l <= nl and nr <= r: mn[node] += v; lz[node] += v; return
        m = (nl + nr) // 2
        upd(2 * node, nl, m, l, r, v); upd(2 * node + 1, m + 1, nr, l, r, v)
        mn[node] = min(mn[2 * node], mn[2 * node + 1]) + lz[node]
    def qry(node, nl, nr, l, r):
        if r < nl or nr < l: return float("inf")
        if l <= nl and nr <= r: return mn[node]
        m = (nl + nr) // 2
        return min(qry(2 * node, nl, m, l, r), qry(2 * node + 1, m + 1, nr, l, r)) + lz[node]
    out = []
    for op in ops:
        if op[0] == 0: upd(1, 0, size - 1, op[1], op[2], op[3])
        else: out.append(qry(1, 0, size - 1, op[1], op[2]))
    return out

