long long qry_(int nd, int nl, int nr, int l, int r) { if (r < nl || nr < l) return LLONG_MAX / 4; if (l <= nl && nr <= r) return mn_[nd]; int m = (nl + nr) / 2; return min(qry_(2*nd, nl, m, l, r), qry_(2*nd+1, m+1, nr, l, r)) + lz_[nd]; }
vector<long long> rangeAddMin(int n, vector<vector<int>>& ops) {
    SZ_ = 1; while (SZ_ < n) SZ_ *= 2; mn_.assign(2 * SZ_, 0); lz_.assign(2 * SZ_, 0);
    for (int i = SZ_ + n; i < 2 * SZ_; i++) mn_[i] = LLONG_MAX / 4; for (int i = SZ_ - 1; i > 0; i--) mn_[i] = min(mn_[2*i], mn_[2*i+1]);
    vector<long long> out; for (auto& o : ops) { if (o[0] == 0) upd_(1, 0, SZ_ - 1, o[1], o[2], o[3]); else out.push_back(qry_(1, 0, SZ_ - 1, o[1], o[2])); } return out;
}
